class EuropeanSocket {
    int outputVoltage220() { return 220; }
}

interface USDevice {
    int getVoltage110();
}

class VoltageAdapter implements USDevice {
    private final EuropeanSocket socket;
    VoltageAdapter(EuropeanSocket socket) { this.socket = socket; }
    public int getVoltage110() {
        return socket.outputVoltage220() / 2;
    }
}

interface DiscountStrategy {
    double apply(double price);
}

class PercentageDiscount implements DiscountStrategy {
    private final double percent;
    PercentageDiscount(double percent) { this.percent = percent; }
    public double apply(double price) { return price * (1 - percent / 100); }
}

class Cart {
    private DiscountStrategy strategy;
    void setStrategy(DiscountStrategy strategy) { this.strategy = strategy; }
    double checkout(double price) { return strategy.apply(price); }
}

class NewsPublisher {
    private final List<Subscriber> subscribers = new ArrayList<>();
    void subscribe(Subscriber s) { subscribers.add(s); }
    void publish(String news) {
        for (Subscriber s : subscribers) {
            s.update(news);
        }
    }
}
